index e0e689f..a7836ce 100644
--- a/src/tests/mc_context_tests.cpp
+++ b/src/tests/mc_context_tests.cpp
@@ -2,6 +2,8 @@
 // SPDX-License-Identifier: Apache-2.0

 #include "compiler/cgir/cg_function.h"
+#include "compiler/cgir/pass/cg_register_class_info.h"
+#include "compiler/cgir/pass/cg_register_info.h"
 #include "compiler/context.h"
 #include "compiler/mir/function.h"
 #include "compiler/target/x86/x86_mc_lowering.h"
@@ -156,3 +158,56 @@ TEST(MCContextReuse, RebuildsAfterALargeObjectAndReturnsToSmallObjectReuse) {
   EXPECT_EQ(&Ctx.getMCContext(), SmallContext);
   EXPECT_EQ(Ctx.getMCContext().lookupSymbol("function_0"), nullptr);
 }
+
+TEST(MCContextReuse,
+     FastRAClassCacheMatchesFreshAcrossReservedRegisterChanges) {
+  CompileContext Ctx;
+  Ctx.initialize();
+  auto &Cached = Ctx.getFastRAClassInfo();
+  unsigned LastTag = 0;
+  const llvm::MCPhysReg *PreviousOrder = nullptr;
+  for (uint32_t I = 0; I < 6; ++I) {
+    MFunction F(Ctx, I);
+    F.setFunctionType(MFunctionType::create(Ctx, Ctx.I32Type, {}));
+    {
+      CgFunction CG(Ctx, F);
+      CG.getRegInfo().freezeReservedRegs(CG);
+      // Simulate a different per-function reservation policy, without adding a
+      // production mutation API solely for this test.
+      if (I >= 2 && I < 4) {
+        auto &Reserved =
+            const_cast<BitVector &>(CG.getRegInfo().getReservedRegs());
+        for (auto Reg : CG.getRegisterInfo().subregs_inclusive(X86::R11)) {
+          Reserved.set(Reg);
+        }
+      }
+      Cached.runOnCgFunction(CG);
+      CgRegisterClassInfo Fresh;
+      Fresh.runOnCgFunction(CG);
+      for (const auto *RC : CG.getRegisterInfo().regclasses()) {
+        const auto A = Cached.getOrder(RC);
+        const auto B = Fresh.getOrder(RC);
+        EXPECT_EQ(std::vector<MCPhysReg>(A.begin(), A.end()),
+                  std::vector<MCPhysReg>(B.begin(), B.end()));
+      }
+      auto Order = Cached.getOrder(&X86::GR64RegClass);
+      EXPECT_EQ(llvm::is_contained(Order, X86::R11), !(I >= 2 && I < 4));
+      if (I == 1) {
+        EXPECT_EQ(Cached.Tag, LastTag);
+        EXPECT_EQ(Order.data(), PreviousOrder);
+      }
+      if (I == 2 || I == 4) {
+        EXPECT_NE(Cached.Tag, LastTag);
+      }
+      LastTag = Cached.Tag;
+      PreviousOrder = Order.data();
+      Cached.releaseFunction();
+    }
+#ifdef NDEBUG
+    F.detachFromPool();
+#endif
+  }
+  EXPECT_EQ(&Ctx.getFastRAClassInfo(), &Cached);
+  CompileContext Other(Ctx);
+  EXPECT_NE(&Other.getFastRAClassInfo(), &Cached);
+}
